INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-baguio-13-120',
        'มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ บากีโอ (คอร์ดิลเลรา)',
        'The Golden Relic Stupa of Baguio (คอร์ดิลเลรา)',
        'sacred',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.3722,
        120.5961,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ลูซอน (ฟิลิปปินส์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว คอร์ดิลเลรา เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Luzon (Philippines), serving as the spiritual heart of ancestral คอร์ดิลเลรา heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ลูซอน (ฟิลิปปินส์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Luzon (Philippines), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน บากีโอ',
        'Remove footwear and maintain silence within the inner terrace of Baguio.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-baguio-13-120',
        'วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ บากีโอ (คอร์ดิลเลรา)',
        'The White Lady Specter of Baguio (คอร์ดิลเลรา)',
        'ghost',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.3722,
        120.5961,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ลูซอน (ฟิลิปปินส์) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ บากีโอ',
        'A chilling paranormal account from Luzon (Philippines). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Baguio.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว คอร์ดิลเลรา ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of คอร์ดิลเลรา oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ บากีโอ',
        'Never whistle or look back if hearing whispers along twilight pathways in Baguio.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-baguio-13-120',
        'อสุรกายพญาเงาแห่งพงไพร บากีโอ (คอร์ดิลเลรา)',
        'The Shadow Beast of Baguio (คอร์ดิลเลรา)',
        'monster',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.3722,
        120.5961,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ลูซอน (ฟิลิปปินส์) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ บากีโอ',
        'Eyewitness reports of a formidable cryptid stalking Luzon (Philippines). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Baguio.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว คอร์ดิลเลรา ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native คอร์ดิลเลรา folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ บากีโอ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Baguio.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"อสุรกายพญาเงาแห่งพงไพร บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-baguio-13-120',
        'คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม บากีโอ (คอร์ดิลเลรา)',
        'The Inscribed Hex and Tragic Fate of Baguio (คอร์ดิลเลรา)',
        'curse',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.3722,
        120.5961,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ลูซอน (ฟิลิปปินส์) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน บากีโอ',
        'A grim cautionary curse chronicle from Luzon (Philippines). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Baguio.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว คอร์ดิลเลรา เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of คอร์ดิลเลรา, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ บากีโอ',
        'Never remove stones, relics, or votive offerings from Baguio.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-baguio-13-120',
        'มหาปราการหินเมกะลิธและแนวสุริยะ บากีโอ (คอร์ดิลเลรา)',
        'The Megalithic Solar Alignments of Baguio (คอร์ดิลเลรา)',
        'legend',
        'ลูซอน (ฟิลิปปินส์)',
        'Luzon (Philippines)',
        'บากีโอ',
        'Baguio',
        16.3722,
        120.5961,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ลูซอน (ฟิลิปปินส์) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว คอร์ดิลเลรา ใน บากีโอ',
        'A legendary monumental marvel in Luzon (Philippines). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral คอร์ดิลเลรา engineers in Baguio.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ลูซอน (ฟิลิปปินส์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Luzon (Philippines), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ บากีโอ',
        'Do not deface, carve, or displace ancient stones in Baguio.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"มหาปราการหินเมกะลิธและแนวสุริยะ บากีโอ (คอร์ดิลเลรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

