        'เว้ (เวียดนาม)',
        'Hue (Vietnam)',
        'นครหลวงเว้',
        'Imperial Hue',
        16.4487,
        107.6359,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เว้ (เวียดนาม) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ราชวงศ์เหงียน เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Hue (Vietnam), serving as the spiritual heart of ancestral ราชวงศ์เหงียน heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เว้ (เวียดนาม) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Hue (Vietnam), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน นครหลวงเว้',
        'Remove footwear and maintain silence within the inner terrace of Imperial Hue.',
        'https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg","title":"เทวสถานศรัทธาแห่งแสงธรรม นครหลวงเว้ (ราชวงศ์เหงียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KsnE0OGg2tk","title":"ตำนาน ปูชนียสถานศักดิ์สิทธิ์และบารมีพระบรมธาตุ","thumbnail":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg"}]'
      );

