        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-amarapura-13-122',
        'อารามโบราณพิทักษ์ผืนป่า อมรปุระ (คองบอง)',
        'The Sacred Mountain Hermitage of Amarapura (คองบอง)',
        'sacred',
        'มัณฑะเลย์ (พม่า)',
        'Mandalay (Myanmar)',
        'อมรปุระ',
        'Amarapura',
        21.9017,
        96.0336,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน มัณฑะเลย์ (พม่า) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว คองบอง เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Mandalay (Myanmar), serving as the spiritual heart of ancestral คองบอง heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค มัณฑะเลย์ (พม่า) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Mandalay (Myanmar), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน อมรปุระ',
        'Remove footwear and maintain silence within the inner terrace of Amarapura.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"อารามโบราณพิทักษ์ผืนป่า อมรปุระ (คองบอง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

