        96.0336,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง มัณฑะเลย์ (พม่า) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน อมรปุระ',
        'A grim cautionary curse chronicle from Mandalay (Myanmar). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Amarapura.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว คองบอง เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of คองบอง, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ อมรปุระ',
        'Never remove stones, relics, or votive offerings from Amarapura.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์ทางแยกสัญญามนต์ดำ อมรปุระ (คองบอง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-amarapura-13-122',
        'แท่นหินดาราศาสตร์และภูมิปัญญาบรรพกาล อมรปุระ (คองบอง)',
        'The Archaeoastronomical Stone Ring of Amarapura (คองบอง)',
        'legend',
        'มัณฑะเลย์ (พม่า)',
        'Mandalay (Myanmar)',
        'อมรปุระ',
        'Amarapura',
        21.9017,
        96.0336,
        'temple_bell',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง มัณฑะเลย์ (พม่า) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว คองบอง ใน อมรปุระ',
        'A legendary monumental marvel in Mandalay (Myanmar). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral คองบอง engineers in Amarapura.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ มัณฑะเลย์ (พม่า) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Mandalay (Myanmar), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ อมรปุระ',
        'Do not deface, carve, or displace ancient stones in Amarapura.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"แท่นหินดาราศาสตร์และภูมิปัญญาบรรพกาล อมรปุระ (คองบอง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-angkor-wat-13-123',
        'มณฑปพระพุทธบาทและรอยจารึกธรรม พระนครวัด (เขมรโบราณ)',
        'The Sacred Footprint and Scripture Shrine of Angkor Wat (เขมรโบราณ)',
        'sacred',
        'เสียมราฐ (กัมพูชา)',
        'Siem Reap (Cambodia)',
        'พระนครวัด',
        'Angkor Wat',
        13.4275,
        103.8967,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เสียมราฐ (กัมพูชา) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เขมรโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Siem Reap (Cambodia), serving as the spiritual heart of ancestral เขมรโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เสียมราฐ (กัมพูชา) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Siem Reap (Cambodia), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน พระนครวัด',
        'Remove footwear and maintain silence within the inner terrace of Angkor Wat.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"มณฑปพระพุทธบาทและรอยจารึกธรรม พระนครวัด (เขมรโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-angkor-wat-13-123',
        'พรายน้ำคร่ำครวญริมสายน้ำ พระนครวัด (เขมรโบราณ)',
        'The Weeping Water Banshee of Angkor Wat (เขมรโบราณ)',
        'ghost',
        'เสียมราฐ (กัมพูชา)',
        'Siem Reap (Cambodia)',
        'พระนครวัด',
        'Angkor Wat',
        13.4275,
        103.8967,
        'water_spirit',
        'เรื่องเล่าสยองขวัญประจำถิ่น เสียมราฐ (กัมพูชา) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ พระนครวัด',
        'A chilling paranormal account from Siem Reap (Cambodia). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Angkor Wat.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เขมรโบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เขมรโบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ พระนครวัด',
        'Never whistle or look back if hearing whispers along twilight pathways in Angkor Wat.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"พรายน้ำคร่ำครวญริมสายน้ำ พระนครวัด (เขมรโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
