        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-angkor-wat-13-123',
        'มนุษย์วานรยักษ์แห่งป่าดึกดำบรรพ์ พระนครวัด (เขมรโบราณ)',
        'The Primeval Forest Ape Cryptid of Angkor Wat (เขมรโบราณ)',
        'monster',
        'เสียมราฐ (กัมพูชา)',
        'Siem Reap (Cambodia)',
        'พระนครวัด',
        'Angkor Wat',
        13.4275,
        103.8967,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เสียมราฐ (กัมพูชา) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ พระนครวัด',
        'Eyewitness reports of a formidable cryptid stalking Siem Reap (Cambodia). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Angkor Wat.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เขมรโบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เขมรโบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ พระนครวัด',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Angkor Wat.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"มนุษย์วานรยักษ์แห่งป่าดึกดำบรรพ์ พระนครวัด (เขมรโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

