        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-manali-13-124',
        'วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ มะนาลี (เวทหิมาลัย)',
        'The Crystal Vihara and Consecrated Icon of Manali (เวทหิมาลัย)',
        'sacred',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2696,
        77.1587,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน หิมาจัลประเทศ (อินเดีย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เวทหิมาลัย เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Himachal Pradesh (India), serving as the spiritual heart of ancestral เวทหิมาลัย heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค หิมาจัลประเทศ (อินเดีย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Himachal Pradesh (India), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน มะนาลี',
        'Remove footwear and maintain silence within the inner terrace of Manali.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-manali-13-124',
        'วิญญาณทหารไร้นามแห่งสมรภูมิเก่า มะนาลี (เวทหิมาลัย)',
        'The Nameless Sentinel Ghost of Manali (เวทหิมาลัย)',
        'ghost',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2696,
        77.1587,
        'creepy_wind',
        'เรื่องเล่าสยองขวัญประจำถิ่น หิมาจัลประเทศ (อินเดีย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ มะนาลี',
        'A chilling paranormal account from Himachal Pradesh (India). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Manali.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เวทหิมาลัย ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เวทหิมาลัย oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ มะนาลี',
        'Never whistle or look back if hearing whispers along twilight pathways in Manali.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"วิญญาณทหารไร้นามแห่งสมรภูมิเก่า มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
