      ) VALUES (
        'pin-legend-jaipur-13-125',
        'กำแพงศิลาและป้อมปราการแห่งกษัตริย์ ชัยปุระ (ราชปุต)',
        'The Cyclopean Stone Fortresses of Jaipur (ราชปุต)',
        'legend',
        'ราชสถาน (อินเดีย)',
        'Rajasthan (India)',
        'ชัยปุระ',
        'Jaipur',
        26.9574,
        75.8023,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ราชสถาน (อินเดีย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ราชปุต ใน ชัยปุระ',
        'A legendary monumental marvel in Rajasthan (India). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ราชปุต engineers in Jaipur.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ราชสถาน (อินเดีย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Rajasthan (India), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ชัยปุระ',
        'Do not deface, carve, or displace ancient stones in Jaipur.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"กำแพงศิลาและป้อมปราการแห่งกษัตริย์ ชัยปุระ (ราชปุต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

