        'pin-sacred-york-13-128',
        'มหารัตนเจดีย์แห่งมโนธรรม ยอร์ก (ไวกิ้งยอร์วิก)',
        'The Great Jeweled Pagoda of York (ไวกิ้งยอร์วิก)',
        'sacred',
        'ยอร์กเชียร์ (อังกฤษ)',
        'Yorkshire (England)',
        'ยอร์ก',
        'York',
        53.9441,
        -1.0365,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ยอร์กเชียร์ (อังกฤษ) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ไวกิ้งยอร์วิก เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Yorkshire (England), serving as the spiritual heart of ancestral ไวกิ้งยอร์วิก heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ยอร์กเชียร์ (อังกฤษ) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Yorkshire (England), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน ยอร์ก',
        'Remove footwear and maintain silence within the inner terrace of York.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหารัตนเจดีย์แห่งมโนธรรม ยอร์ก (ไวกิ้งยอร์วิก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-york-13-128',
        'วิญญาณคนเฝ้าประภาคารผู้ล่วงลับ ยอร์ก (ไวกิ้งยอร์วิก)',
        'The Restless Keeper of York (ไวกิ้งยอร์วิก)',
        'ghost',
        'ยอร์กเชียร์ (อังกฤษ)',
        'Yorkshire (England)',
        'ยอร์ก',
        'York',
        53.9441,
        -1.0365,
        'creepy_wind',
        'เรื่องเล่าสยองขวัญประจำถิ่น ยอร์กเชียร์ (อังกฤษ) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ ยอร์ก',
        'A chilling paranormal account from Yorkshire (England). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of York.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ไวกิ้งยอร์วิก ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ไวกิ้งยอร์วิก oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ ยอร์ก',
        'Never whistle or look back if hearing whispers along twilight pathways in York.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"วิญญาณคนเฝ้าประภาคารผู้ล่วงลับ ยอร์ก (ไวกิ้งยอร์วิก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
