        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-york-13-128',
        'สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง ยอร์ก (ไวกิ้งยอร์วิก)',
        'The Night Livestock Stalker of York (ไวกิ้งยอร์วิก)',
        'monster',
        'ยอร์กเชียร์ (อังกฤษ)',
        'Yorkshire (England)',
        'ยอร์ก',
        'York',
        53.9441,
        -1.0365,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ยอร์กเชียร์ (อังกฤษ) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ยอร์ก',
        'Eyewitness reports of a formidable cryptid stalking Yorkshire (England). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across York.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ไวกิ้งยอร์วิก ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ไวกิ้งยอร์วิก folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ยอร์ก',
        'Never follow unfamiliar predator tracks into deep forest after sunset in York.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง ยอร์ก (ไวกิ้งยอร์วิก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
