        'เรื่องเล่าสยองขวัญประจำถิ่น คอร์นวอลล์ (อังกฤษ) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ เพนแซนซ์',
        'A chilling paranormal account from Cornwall (England). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Penzance.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เซลติกบริตัน ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เซลติกบริตัน oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ เพนแซนซ์',
        'Never whistle or look back if hearing whispers along twilight pathways in Penzance.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน เพนแซนซ์ (เซลติกบริตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-penzance-13-129',
        'พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน เพนแซนซ์ (เซลติกบริตัน)',
        'The Black-Scaled Serpent of Penzance (เซลติกบริตัน)',
        'monster',
        'คอร์นวอลล์ (อังกฤษ)',
        'Cornwall (England)',
        'เพนแซนซ์',
        'Penzance',
        50.1186,
        -5.5522,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน คอร์นวอลล์ (อังกฤษ) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เพนแซนซ์',
        'Eyewitness reports of a formidable cryptid stalking Cornwall (England). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Penzance.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เซลติกบริตัน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เซลติกบริตัน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เพนแซนซ์',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Penzance.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน เพนแซนซ์ (เซลติกบริตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-penzance-13-129',
        'อาถรรพ์รูปเคารพและดวงตาจ้องมอง เพนแซนซ์ (เซลติกบริตัน)',
        'The Cursed Effigy Gaze of Penzance (เซลติกบริตัน)',
        'curse',
        'คอร์นวอลล์ (อังกฤษ)',
        'Cornwall (England)',
        'เพนแซนซ์',
        'Penzance',
        50.1186,
        -5.5522,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง คอร์นวอลล์ (อังกฤษ) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เพนแซนซ์',
        'A grim cautionary curse chronicle from Cornwall (England). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Penzance.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เซลติกบริตัน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เซลติกบริตัน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เพนแซนซ์',
        'Never remove stones, relics, or votive offerings from Penzance.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"อาถรรพ์รูปเคารพและดวงตาจ้องมอง เพนแซนซ์ (เซลติกบริตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-penzance-13-129',
        'รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ เพนแซนซ์ (เซลติกบริตัน)',
        'The Undeciphered Glyph Stele of Penzance (เซลติกบริตัน)',
        'legend',
        'คอร์นวอลล์ (อังกฤษ)',
        'Cornwall (England)',
        'เพนแซนซ์',
        'Penzance',
        50.1186,
        -5.5522,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง คอร์นวอลล์ (อังกฤษ) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เซลติกบริตัน ใน เพนแซนซ์',
        'A legendary monumental marvel in Cornwall (England). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เซลติกบริตัน engineers in Penzance.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ คอร์นวอลล์ (อังกฤษ) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Cornwall (England), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เพนแซนซ์',
        'Do not deface, carve, or displace ancient stones in Penzance.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ เพนแซนซ์ (เซลติกบริตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

