INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-curragh-14-130',
        'คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม เคอร์ราห์ (เกลิกไอริช)',
        'The Inscribed Hex and Tragic Fate of Curragh (เกลิกไอริช)',
        'curse',
        'เคาน์ตีคิลแดร์ (ไอร์แลนด์)',
        'County Kildare (Ireland)',
        'เคอร์ราห์',
        'Curragh',
        53.1739,
        -6.7994,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เคาน์ตีคิลแดร์ (ไอร์แลนด์) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เคอร์ราห์',
        'A grim cautionary curse chronicle from County Kildare (Ireland). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Curragh.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เกลิกไอริช เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เกลิกไอริช, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เคอร์ราห์',
        'Never remove stones, relics, or votive offerings from Curragh.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม เคอร์ราห์ (เกลิกไอริช)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-curragh-14-130',
        'มหาปราการหินเมกะลิธและแนวสุริยะ เคอร์ราห์ (เกลิกไอริช)',
        'The Megalithic Solar Alignments of Curragh (เกลิกไอริช)',
        'legend',
        'เคาน์ตีคิลแดร์ (ไอร์แลนด์)',
        'County Kildare (Ireland)',
        'เคอร์ราห์',
        'Curragh',
        53.1739,
        -6.7994,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เคาน์ตีคิลแดร์ (ไอร์แลนด์) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เกลิกไอริช ใน เคอร์ราห์',
        'A legendary monumental marvel in County Kildare (Ireland). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เกลิกไอริช engineers in Curragh.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เคาน์ตีคิลแดร์ (ไอร์แลนด์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in County Kildare (Ireland), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เคอร์ราห์',
        'Do not deface, carve, or displace ancient stones in Curragh.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"มหาปราการหินเมกะลิธและแนวสุริยะ เคอร์ราห์ (เกลิกไอริช)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
