        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-rennes-14-134',
        'วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ แรนส์ (เบรอตง)',
        'The Crystal Vihara and Consecrated Icon of Rennes (เบรอตง)',
        'sacred',
        'บริตตานี (ฝรั่งเศส)',
        'Brittany (France)',
        'แรนส์',
        'Rennes',
        48.0873,
        -1.6778,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน บริตตานี (ฝรั่งเศส) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เบรอตง เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Brittany (France), serving as the spiritual heart of ancestral เบรอตง heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค บริตตานี (ฝรั่งเศส) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Brittany (France), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน แรนส์',
        'Remove footwear and maintain silence within the inner terrace of Rennes.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ แรนส์ (เบรอตง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

