      ) VALUES (
        'pin-sacred-siena-14-137',
        'เทวาลัยโบราณแห่งมหาเทวะ ซีเอนา (อีทรัสคัน)',
        'The Ancient Chola Shiva Shrine of Siena (อีทรัสคัน)',
