      ) VALUES (
        'pin-legend-siena-14-137',
        'ยอดผาโทรลล์และรอยเท้าบรรพชนยักษ์ ซีเอนา (อีทรัสคัน)',
        'The Petrified Giant Cliffs of Siena (อีทรัสคัน)',
        'legend',
        'ทัสคานี (อิตาลี)',
        'Tuscany (Italy)',
        'ซีเอนา',
        'Siena',
        43.3338,
        11.3608,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ทัสคานี (อิตาลี) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว อีทรัสคัน ใน ซีเอนา',
        'A legendary monumental marvel in Tuscany (Italy). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral อีทรัสคัน engineers in Siena.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ทัสคานี (อิตาลี) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Tuscany (Italy), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ซีเอนา',
        'Do not deface, carve, or displace ancient stones in Siena.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"ยอดผาโทรลล์และรอยเท้าบรรพชนยักษ์ ซีเอนา (อีทรัสคัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

