      ) VALUES (
        'pin-legend-granada-14-139',
        'รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ กรานาดา (มัวร์อัลอันดาลุส)',
        'The Undeciphered Glyph Stele of Granada (มัวร์อัลอันดาลุส)',
        'legend',
        'อันดาลูซิอา (สเปน)',
        'Andalusia (Spain)',
        'กรานาดา',
        'Granada',
        37.2223,
        -3.5836,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง อันดาลูซิอา (สเปน) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว มัวร์อัลอันดาลุส ใน กรานาดา',
        'A legendary monumental marvel in Andalusia (Spain). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral มัวร์อัลอันดาลุส engineers in Granada.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ อันดาลูซิอา (สเปน) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Andalusia (Spain), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ กรานาดา',
        'Do not deface, carve, or displace ancient stones in Granada.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ กรานาดา (มัวร์อัลอันดาลุส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );